  const style = document.createElement('style');
  style.textContent = `.globe-home{position:relative;max-width:1180px;margin:0 auto;z-index:1}.globe-stage{position:relative;height:390px;overflow:hidden;background:radial-gradient(circle at 50% 48%,#ffffff 0,#f5fcf8 47%,transparent 73%)}.globe-canvas{display:block;width:100%;height:100%}.globe-title,.globe-sub,.globe-host,.globe-clients,.globe-legend,.globe-controls{display:none}.gauge-card{position:relative;z-index:2;margin-top:-54px;background:rgba(255,255,255,.56)!important;border-color:rgba(255,255,255,.72)!important;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);box-shadow:0 8px 24px rgba(31,106,79,.10)}.gauge-card .two-gauges{grid-template-columns:repeat(2,minmax(0,1fr));max-width:520px;margin:0 auto}.gauge-card .two-gauges .gauge{padding:4px}.home-week{max-width:1180px;margin:12px auto}.home-week .week-card{padding:14px 16px}.week-card h2{margin:0 0 8px;font-size:16px}.week-bars{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px;align-items:end;height:118px}.week-bar{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:3px;height:100%}.week-bar i{display:block;width:100%;max-width:22px;border-radius:6px 6px 2px 2px;background:#2fbf7a;min-height:4px}.week-bar b{color:var(--ink);font-size:10px;font-weight:700;line-height:1}.week-bar span{color:var(--muted);font-size:10px}@media(max-width:800px),(max-aspect-ratio:3/4){.globe-stage{height:315px}.gauge-card{margin-top:-42px}.gauge-card .two-gauges{max-width:360px}.home-week .week-bars{height:108px}}`;
  document.head.append(style);
  const esc = window.esc || (value => String(value));
  const state = { rotation: 0, last: 0 };
  let canvas, ctx, animation;
  function bytes(n) { return window.bytes ? window.bytes(n) : String(n || 0); }
  function project(lon, lat, rotation, radius, cx, cy) {
    const d = ((lon + rotation + 540) % 360) - 180, lonR = d * Math.PI / 180, latR = lat * Math.PI / 180;
    return { x: cx + Math.cos(latR) * Math.sin(lonR) * radius, y: cy - Math.sin(latR) * radius * .92, z: Math.cos(latR) * Math.cos(lonR) };
  }
