    const lineHeight = size + 3; ctx.font = `600 ${size}px system-ui,-apple-system,sans-serif`; ctx.textBaseline = 'middle';
    const width = Math.max(...lines.map(line => ctx.measureText(line).width)) + 12, height = lines.length * lineHeight + 7;
    ctx.fillStyle = 'rgba(255,255,255,.90)'; ctx.beginPath(); ctx.roundRect(x, y - height / 2, width, height, 7); ctx.fill();
